    "position": "岗位",
    "effective_date": "生效日期",
    "phone": "电话",
    "email": "邮箱",
}
EMPLOYEE_COLUMNS = (
    "id", "name", "employee_no", "department", "position",
    "effective_date", "phone", "email", "status",
)


